import { VStack } from "@chakra-ui/react";

type MintedProps = {
  minted: number | undefined;
};

function MintedBox(props: MintedProps) {
  return (
    <VStack>
      <span>Minted</span>
      <span>{props.minted ? props.minted.toString() : "-"}</span>
    </VStack>
  );
}

export default MintedBox;
